class BadHashFields(id: String, name: String) {
    private val id = id
    private val name = name // bad

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is BadHashFields) return false
        return id == other.id && name == other.name
    }

    override fun hashCode(): Int {
        return id.hashCode()
    }
}

class GoodHashFieldsExplicit(id: String, name: String) {
    private val id = id
    private val name = name

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is GoodHashFieldsExplicit) return false
        return id == other.id && name == other.name
    }

    override fun hashCode(): Int {
        return 31 * id.hashCode() + name.hashCode()
    }
}

class PlainHashFields(id: String, name: String) {
    private val id = id
    private val name = name
}
